<?php require '../config.php';if(admin()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$st=db()->prepare("SELECT id,password_hash FROM admins WHERE email=?");$st->bind_param('s',$email);$st->execute();$a=one($st);if($a&&password_verify($pass,$a['password_hash'])){$_SESSION['admin_id']=$a['id'];header('Location:index.php');exit;}$err='Invalid credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin · DisputeDesk</title><link rel="stylesheet" href="../assets/style.css"></head><body class="login"><div class="login-card"><a class="logo" href="../index.php"><span class="logo-icon">D</span>DisputeDesk</a><div class="kicker"><span></span> ADMIN CONSOLE</div><h1>Case operations.</h1><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input type="email" name="email" value="<?=h(ADMIN_EMAIL)?>" required></label><label>Password<input type="password" name="password" value="<?=h(ADMIN_PASSWORD)?>" required></label><button class="btn dark full">Sign in</button></form><small>Default: <?=h(ADMIN_EMAIL)?> / <?=h(ADMIN_PASSWORD)?></small></div></body></html>